cat > /tmp/snap.sh <<'EOF'
#!/bin/bash
# usage: snap.sh thing1 thing2 ... ; prints selected features
cd /home/judge/solution/deploy/compose && set -a && . ./.env && set +a
D="http://127.0.0.1:${DITTO_PORT:-8080}"
for t in "$@"; do curl -s -u ditto:$DITTO_PASSWORD "$D/api/2/things/kz.aktogay:$t?fields=features" | python3 -c "
import json,sys;d=json.load(sys.stdin);f=d.get('features',{});
out={}
for k,v in f.items():
  for kk,vv in v.get('properties',{}).items():
    val=vv.get('value') if isinstance(vv,dict) and 'value' in vv else vv
    if isinstance(val,(int,float,str)) and (not isinstance(val,str) or len(val)<160): out[kk]=val
print('$t',json.dumps(out,ensure_ascii=False)[:900])"; done
EOF
chmod +x /tmp/snap.sh; /tmp/snap.sh site control crusher-1 stockpile-1 line-1

